var import_crypto8 = __toESM(require("crypto"));
function initAuditTables() {
  const db2 = getDb();
  db2.exec(`
    CREATE TABLE IF NOT EXISTS audit_logs (
      id TEXT PRIMARY KEY,
      userId TEXT NOT NULL DEFAULT '',
      category TEXT NOT NULL,
      action TEXT NOT NULL,
      level TEXT NOT NULL DEFAULT 'info',
      targetType TEXT DEFAULT '',
      targetId TEXT DEFAULT '',
      details TEXT DEFAULT '',
      ip TEXT DEFAULT '',
      userAgent TEXT DEFAULT '',
      createdAt TEXT NOT NULL DEFAULT (datetime('now'))
    );

    CREATE INDEX IF NOT EXISTS idx_audit_user ON audit_logs(userId);
    CREATE INDEX IF NOT EXISTS idx_audit_category ON audit_logs(category);
    CREATE INDEX IF NOT EXISTS idx_audit_time ON audit_logs(createdAt DESC);
    CREATE INDEX IF NOT EXISTS idx_audit_target ON audit_logs(targetType, targetId);
  `);
}
var AuditLogger = class _AuditLogger {
  static instance;
  static getInstance() {
    if (!this.instance) {
      this.instance = new _AuditLogger();
    }
    return this.instance;
  }
  /** 记录审计日志 */
  log(params2) {
    try {
      const db2 = getDb();
      const id2 = import_crypto8.default.randomUUID();
      const details = typeof params2.details === "object" ? JSON.stringify(params2.details) : params2.details || "";
      db2.prepare(`
        INSERT INTO audit_logs (id, userId, category, action, level, targetType, targetId, details, ip, userAgent)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      `).run(
        id2,
        params2.userId || "",
        params2.category,
        params2.action,
        params2.level || "info",
        params2.targetType || "",
        params2.targetId || "",
        details.slice(0, 5e3),
        // 限制大小
        params2.ip || "",
        params2.userAgent || ""
      );
    } catch (err) {
      console.error("[Audit] \u65E5\u5FD7\u8BB0\u5F55\u5931\u8D25:", err.message);
    }
  }
  /** 查询审计日志 */
  query(params2) {
    const db2 = getDb();
    const conditions = [];
    const values2 = [];
    if (params2.userId) {
      conditions.push("userId = ?");
      values2.push(params2.userId);
    }
    if (params2.category) {
      conditions.push("category = ?");
      values2.push(params2.category);
    }
    if (params2.level) {
      conditions.push("level = ?");
      values2.push(params2.level);
    }
    if (params2.targetType) {
      conditions.push("targetType = ?");
      values2.push(params2.targetType);
    }
    if (params2.targetId) {
      conditions.push("targetId = ?");
      values2.push(params2.targetId);
    }
    if (params2.dateFrom) {
      conditions.push("createdAt >= ?");
      values2.push(params2.dateFrom);
    }
    if (params2.dateTo) {
      conditions.push("createdAt <= ?");
      values2.push(params2.dateTo);
    }
    const where2 = conditions.length > 0 ? `WHERE ${conditions.join(" AND ")}` : "";
    const limit = Math.min(params2.limit || 50, 200);
    const offset = params2.offset || 0;
    const total = db2.prepare(`SELECT COUNT(*) as count FROM audit_logs ${where2}`).get(...values2).count;
    const logs = db2.prepare(
      `SELECT * FROM audit_logs ${where2} ORDER BY createdAt DESC LIMIT ? OFFSET ?`
    ).all(...values2, limit, offset);
    return { logs, total };
  }
  /** 清理过期日志（保留指定天数） */
  cleanup(retentionDays = 90) {
    const db2 = getDb();
    const cutoff = new Date(Date.now() - retentionDays * 864e5).toISOString();
    const result2 = db2.prepare("DELETE FROM audit_logs WHERE createdAt < ?").run(cutoff);
    return result2.changes;
  }
};
var auditLogger = AuditLogger.getInstance();
function logAudit(userId, category, action, details, extra) {
  auditLogger.log({
    userId,
    category,
    action,
    details,
    ...extra || {}
  });
}

