            size: { type: "integer" },
            createdAt: { type: "string", format: "date-time" },
            category: { type: "string", enum: ["image", "file"] },
            url: { type: "string" },
            thumbnailUrl: { type: "string" },
            hash: { type: "string", nullable: true },
